if (response.status !== undefined && Number(response.status) !== 1) {
    throw new Error("Artwork API error " + response.status);
}
var list = response.data || [];
if (!list.length) return [];
var cover = list[0].dycover;
if (!cover) return [];
var url = cover.h264_url || cover.h265_url || "";
if (!url) return [];
url = url.replace(/^http:/i, "https:");
return [{coverUrl: url, mimeType: "video/mp4", kind: "video"}];

